CREATE TABLE IF NOT EXISTS jurisdictions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), country_name text NOT NULL, iso_code text, region text, capital_city text, legal_system text, currency text, status text NOT NULL DEFAULT 'Research', group_relationship text, local_law_review_required boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jurisdiction_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES jurisdictions(id) ON DELETE CASCADE, governance_model text, company_law_framework text, foreign_investment_framework text, tax_framework text, land_regime_summary text, customary_rights_summary text, environmental_framework text, data_protection_framework text, dispute_resolution_framework text, fx_capital_control_summary text, last_reviewed date, evidence_reference text, status text NOT NULL DEFAULT 'Draft');
CREATE TABLE IF NOT EXISTS local_entities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES jurisdictions(id) ON DELETE CASCADE, legal_name text NOT NULL, entity_type text NOT NULL, registration_number text, ownership_model text, local_directors_required text, parent_entity_reference text, status text NOT NULL DEFAULT 'Proposed', evidence_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS local_regulators (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES jurisdictions(id) ON DELETE CASCADE, regulator_name text NOT NULL, mandate text, regulated_activity text, official_reference text, status text NOT NULL DEFAULT 'Research');
CREATE TABLE IF NOT EXISTS jurisdiction_obligations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES jurisdictions(id) ON DELETE CASCADE, obligation_code text NOT NULL, title text NOT NULL, category text NOT NULL, description text NOT NULL, regulator text, frequency text, evidence_required text, status text NOT NULL DEFAULT 'To Be Assessed', legal_review_required boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS local_licences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES jurisdictions(id) ON DELETE CASCADE, licence_name text NOT NULL, activity text NOT NULL, regulator text, licence_number text, issue_date date, expiry_date date, status text NOT NULL DEFAULT 'Not Recorded', evidence_reference text);
CREATE TABLE IF NOT EXISTS land_rights_frameworks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES jurisdictions(id) ON DELETE CASCADE, land_tenure_type text NOT NULL, foreign_ownership_position text, customary_land_position text, community_rights_position text, registration_authority text, title_evidence_requirements text, transfer_constraints text, compulsory_acquisition_rules text, status text NOT NULL DEFAULT 'Research', legal_review_required boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS indigenous_customary_rights (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES jurisdictions(id) ON DELETE CASCADE, rights_category text NOT NULL, rights_holder_description text NOT NULL, legal_basis text, consultation_requirement text, consent_requirement text, benefit_sharing_requirement text, heritage_protection_requirement text, evidence_reference text, status text NOT NULL DEFAULT 'Research', legal_review_required boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS jurisdiction_tax_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES jurisdictions(id) ON DELETE CASCADE, tax_type text NOT NULL, authority text, headline_rate_or_rule text, filing_frequency text, withholding_or_cross_border_rule text, transfer_or_asset_tax_rule text, evidence_reference text, status text NOT NULL DEFAULT 'Research', legal_review_required boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS investment_restrictions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES jurisdictions(id) ON DELETE CASCADE, sector text NOT NULL, restriction_type text NOT NULL, restriction_summary text NOT NULL, approval_authority text, ownership_cap text, licensing_requirement text, evidence_reference text, status text NOT NULL DEFAULT 'Research', legal_review_required boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS country_risk_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES jurisdictions(id) ON DELETE CASCADE, political_risk text DEFAULT 'Unassessed', legal_risk text DEFAULT 'Unassessed', currency_risk text DEFAULT 'Unassessed', transfer_risk text DEFAULT 'Unassessed', operational_risk text DEFAULT 'Unassessed', rights_risk text DEFAULT 'Unassessed', environmental_risk text DEFAULT 'Unassessed', overall_rating text DEFAULT 'Unassessed', assessment_date date, assessment_basis text, status text NOT NULL DEFAULT 'Draft');
CREATE TABLE IF NOT EXISTS treaty_and_cross_border_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES jurisdictions(id) ON DELETE CASCADE, rule_type text NOT NULL, counterparty_jurisdiction text, instrument_name text, subject text NOT NULL, effect_summary text, effective_date date, evidence_reference text, status text NOT NULL DEFAULT 'Research', legal_review_required boolean NOT NULL DEFAULT true);
INSERT INTO jurisdictions(country_name,iso_code,region,currency,status,group_relationship) SELECT 'Nigeria','NG','West Africa','NGN','Home Jurisdiction','Current Group Base' WHERE NOT EXISTS (SELECT 1 FROM jurisdictions WHERE iso_code='NG');
INSERT INTO jurisdictions(country_name,iso_code,region,currency,status,group_relationship) SELECT 'Ghana','GH','West Africa','GHS','Expansion Candidate','Future Jurisdiction' WHERE NOT EXISTS (SELECT 1 FROM jurisdictions WHERE iso_code='GH');
INSERT INTO jurisdictions(country_name,iso_code,region,currency,status,group_relationship) SELECT 'Kenya','KE','East Africa','KES','Expansion Candidate','Future Jurisdiction' WHERE NOT EXISTS (SELECT 1 FROM jurisdictions WHERE iso_code='KE');
INSERT INTO jurisdictions(country_name,iso_code,region,currency,status,group_relationship) SELECT 'South Africa','ZA','Southern Africa','ZAR','Expansion Candidate','Future Jurisdiction' WHERE NOT EXISTS (SELECT 1 FROM jurisdictions WHERE iso_code='ZA');
INSERT INTO jurisdictions(country_name,iso_code,region,currency,status,group_relationship) SELECT 'Côte d’Ivoire','CI','West Africa','XOF','Expansion Candidate','Future Jurisdiction' WHERE NOT EXISTS (SELECT 1 FROM jurisdictions WHERE iso_code='CI');
INSERT INTO jurisdictions(country_name,iso_code,region,currency,status,group_relationship) SELECT 'Rwanda','RW','East Africa','RWF','Expansion Candidate','Future Jurisdiction' WHERE NOT EXISTS (SELECT 1 FROM jurisdictions WHERE iso_code='RW');
INSERT INTO jurisdiction_profiles(jurisdiction_id,status) SELECT id,'Draft' FROM jurisdictions j WHERE j.iso_code='NG' AND NOT EXISTS (SELECT 1 FROM jurisdiction_profiles p WHERE p.jurisdiction_id=j.id);
INSERT INTO country_risk_profiles(jurisdiction_id,status) SELECT id,'Draft' FROM jurisdictions j WHERE NOT EXISTS (SELECT 1 FROM country_risk_profiles c WHERE c.jurisdiction_id=j.id);